import{_ as t,a0 as p,w as o,s as d,I as i,x as a,a1 as n,A as l,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"了解一下 Fossil，一个 Git 的替代品 | LCTT x X-CMD","titleTemplate":false,"description":"了解一下 Fossil，一个 Git 的替代品 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"了解一下 Fossil，一个 Git 的替代品 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"了解一下 Fossil，一个 Git 的替代品 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201125 Get started with Fossil, an alternative to Git","title":"了解一下 Fossil，一个 Git 的替代品","tag":"202012","desc":""},"relativePath":"202012/20201125 Get started with Fossil, an alternative to Git.md","filePath":"[post].md"}'),c={name:"202012/20201125 Get started with Fossil, an alternative to Git.md"};function h(g,s,u,k,b,f){const e=p("Link");return o(),d("div",null,[s[26]||(s[26]=i("h1",{id:"了解一下-fossil-一个-git-的替代品",tabindex:"-1"},[a("了解一下 Fossil，一个 Git 的替代品 "),i("a",{class:"header-anchor",href:"#了解一下-fossil-一个-git-的替代品","aria-label":"Permalink to “了解一下 Fossil，一个 Git 的替代品”"},"​")],-1)),s[27]||(s[27]=i("blockquote",null,[i("p",null,"Fossil 是一个集版本控制系统、bug 追踪、维基、论坛以及文档解决方案于一体的系统。")],-1)),s[28]||(s[28]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202012/01/173057hfhyzyw921zll219.jpg",alt:""})],-1)),s[29]||(s[29]=i("p",null,"每个开发者都知道，追踪代码的修改是至关重要的。有时候你会处于好奇或者教育的目的需要展示你的项目开始和进化的历史。有时候你想让其他的开发者参与到你的项目中，因此你需要一种值得信赖的能合并不同代码分支的方法。更极端一点，有时候你为了解决一个问题而修改的代码导致已有的功能不能正常使用。",-1)),i("p",null,[n(e,{href:"https://fossil-scm.org/home/doc/trunk/www/index.wiki"},{default:l(()=>[...s[0]||(s[0]=[a("Fossil",-1)])]),_:1}),s[2]||(s[2]=a(" 源码管理系统是由著名的 ",-1)),n(e,{href:"https://www.sqlite.org/index.html"},{default:l(()=>[...s[1]||(s[1]=[a("SQLite",-1)])]),_:1}),s[3]||(s[3]=a(" 数据库的作者开发的一个集版本控制系统、bug 追踪、维基、论坛以及文档解决方案于一体的系统。",-1))]),s[30]||(s[30]=i("h3",{id:"安装-fossil",tabindex:"-1"},[a("安装 Fossil "),i("a",{class:"header-anchor",href:"#安装-fossil","aria-label":"Permalink to “安装 Fossil”"},"​")],-1)),i("p",null,[s[6]||(s[6]=a("Fossil 是一个独立的 C 程序，因此你可以从它的网站上",-1)),n(e,{href:"https://fossil-scm.org/home/uv/download.html"},{default:l(()=>[...s[4]||(s[4]=[a("下载",-1)])]),_:1}),s[7]||(s[7]=a("后放在环境变量 ",-1)),n(e,{href:"https://opensource.com/article/17/6/set-path-linux"},{default:l(()=>[...s[5]||(s[5]=[a("PATH",-1)])]),_:1}),s[8]||(s[8]=a(" 中的任意位置。例如，假定 ",-1)),s[9]||(s[9]=i("code",null,"/usr/local/bin",-1)),s[10]||(s[10]=a(" 已经在你的环境变量中（默认情况下是在的）：",-1))]),s[31]||(s[31]=r(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget https://fossil-scm.org/home/uv/fossil-linux-x64-X.Y.tar.gz</span></span>
<span class="line"><span>$ sudo tar xvf fossil-linux-x64-X.Y.tar.gz --directory /usr/local/bin</span></span></code></pre></div><p>你也可以通过包管理器从软件仓库中找到 Fossil，或者直接从源码编译。</p><h3 id="创建一个-fossil-仓库" tabindex="-1">创建一个 Fossil 仓库 <a class="header-anchor" href="#创建一个-fossil-仓库" aria-label="Permalink to “创建一个 Fossil 仓库”">​</a></h3><p>如果你已经有一个代码项目，想用 Fossil 来追踪，那么第一步就是创建一个 Fossil 仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fossil init myproject.fossil</span></span>
<span class="line"><span>project-id: 010836ac6112fefb0b015702152d447c8c1d8604</span></span>
<span class="line"><span>server-id:  54d837e9dc938ba1caa56d31b99c35a4c9627f44</span></span>
<span class="line"><span>admin-user: klaatu (initial password is &quot;14b605&quot;)</span></span></code></pre></div><p>创建 Fossil 仓库的过程中会返回三行信息：一个唯一的项目 ID、一个唯一的服务器 ID 以及管理员 ID 和密码。项目 ID 和服务器 ID 是版本数字。管理员凭证表明你对这个仓库的所有权，当你把 Fossil 作为服务器让其他用户来访问时可以使用管理员权限。</p><h3 id="fossil-仓库工作流" tabindex="-1">Fossil 仓库工作流 <a class="header-anchor" href="#fossil-仓库工作流" aria-label="Permalink to “Fossil 仓库工作流”">​</a></h3><p>在你使用 Fossil 仓库之前，你需要先为它的数据创建一个工作路径。你可以把这个过程类比为使用 Python 时创建一个虚拟环境或者解压一个只用来备份的 ZIP 文件。</p><p>创建一个工作目录并进入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir myprojectdir</span></span>
<span class="line"><span>$ cd myprojectdir</span></span></code></pre></div><p>把你的 Fossil 打开到刚刚创建的目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fossil open ../myproject</span></span>
<span class="line"><span>project-name: &lt;unnamed&gt;</span></span>
<span class="line"><span>repository:   /home/klaatu/myprojectdir/../myproject</span></span>
<span class="line"><span>local-root:   /home/klaatu/myprojectdir/</span></span>
<span class="line"><span>config-db:    /home/klaatu/.fossil</span></span>
<span class="line"><span>project-code: 010836ac6112fefb0b015702152d447c8c1d8604</span></span>
<span class="line"><span>checkout:     9e6cd96dd675544c58a246520ad58cdd460d1559 2020-11-09 04:09:35 UTC</span></span>
<span class="line"><span>tags:         trunk</span></span>
<span class="line"><span>comment:      initial empty check-in (user: klaatu)</span></span>
<span class="line"><span>check-ins:    1</span></span></code></pre></div><p>你可能注意到了，Fossil 在你的家目录下创建了一个名为 <code>.fossil</code> 的隐藏文件，用来追踪你的全局 Fossil 配置。这个配置不是只适用于你的一个项目的；这个文件只会在你第一次使用 Fossil 时生成。</p><h4 id="添加文件" tabindex="-1">添加文件 <a class="header-anchor" href="#添加文件" aria-label="Permalink to “添加文件”">​</a></h4><p>使用 <code>add</code> 和 <code>commit</code> 子命令来向你的仓库添加文件。例如，创建一个简单的 <code>README</code> 文件，把它添加到仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;My first Fossil project&quot; &gt; README</span></span>
<span class="line"><span>$ fossil add README</span></span>
<span class="line"><span>ADDED  README</span></span>
<span class="line"><span>$ fossil commit -m &#39;My first commit&#39;</span></span>
<span class="line"><span>New_Version: 2472a43acd11c93d08314e852dedfc6a476403695e44f47061607e4e90ad01aa</span></span></code></pre></div><h4 id="使用分支" tabindex="-1">使用分支 <a class="header-anchor" href="#使用分支" aria-label="Permalink to “使用分支”">​</a></h4><p>Fossil 仓库开始时默认使用的主分支名为 <code>trunk</code>。当你想修改代码而又不影响主干代码时，你可以从 trunk 分支切走。创建新分支需要使用 <code>branch</code> 子命令，这个命令需要两个参数：一个新分支的名字，一个新分支的基分支名字。在本例中，只有一个分支 <code>trunk</code>，因此尝试创建一个名为 <code>dev</code> 的新分支：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fossil branch --help</span></span>
<span class="line"><span>Usage: fossil branch new BRANCH-NAME BASIS ?OPTIONS?</span></span>
<span class="line"><span>$ fossil branch new dev trunk</span></span>
<span class="line"><span>New branch: cb90e9c6f23a9c98e0c3656d7e18d320fa52e666700b12b5ebbc4674a0703695</span></span></code></pre></div><p>你已经创建了一个新分支，但是你当前所在的分支仍然是 <code>trunk</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fossil branch current</span></span>
<span class="line"><span>trunk</span></span></code></pre></div><p>使用 <code>checkout</code> 命令切换到你的新分支 <code>dev</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fossil checkout dev</span></span>
<span class="line"><span>dev</span></span></code></pre></div><h4 id="合并修改" tabindex="-1">合并修改 <a class="header-anchor" href="#合并修改" aria-label="Permalink to “合并修改”">​</a></h4><p>假设你在 <code>dev</code> 分支中添加了一个新文件，完成了测试，现在想把它合并到 <code>trunk</code>。这个过程叫做<em>合并</em>。</p><p>首先，切回目标分支（本例中目标分支为 <code>trunk</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fossil checkout trunk</span></span>
<span class="line"><span>trunk</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>README</span></span></code></pre></div><p>这个分支中没有你的新文件（或者你对其他文件的修改），而那些内容是合并的过程需要的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fossil merge dev</span></span>
<span class="line"><span> &quot;fossil undo&quot; is available to undo changes to the working checkout.</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>myfile.lua  README</span></span></code></pre></div><h3 id="查看-fossil-时间线" tabindex="-1">查看 Fossil 时间线 <a class="header-anchor" href="#查看-fossil-时间线" aria-label="Permalink to “查看 Fossil 时间线”">​</a></h3><p>使用 <code>timeline</code> 选项来查看仓库的历史。这个命令列出了你的仓库的所有活动的详细信息，包括用来表示每次修改的哈希值、每次提交时填写的信息以及提交者：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fossil timeline</span></span>
<span class="line"><span>=== 2020-11-09 ===</span></span>
<span class="line"><span>06:24:16 [5ef06e668b] added exciting new file (user: klaatu tags: dev)</span></span>
<span class="line"><span>06:11:19 [cb90e9c6f2] Create new branch named &quot;dev&quot; (user: klaatu tags: dev)</span></span>
<span class="line"><span>06:08:09 [a2bb73e4a3] *CURRENT* some additions were made (user: klaatu tags: trunk)</span></span>
<span class="line"><span>06:00:47 [2472a43acd] This is my first commit. (user: klaatu tags: trunk)</span></span>
<span class="line"><span>04:09:35 [9e6cd96dd6] initial empty check-in (user: klaatu tags: trunk)</span></span>
<span class="line"><span>+++ no more data (5) +++</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/fossil-ui.jpg" alt="Fossil UI" title="Fossil UI"></p><h3 id="公开你的-fossil-仓库" tabindex="-1">公开你的 Fossil 仓库 <a class="header-anchor" href="#公开你的-fossil-仓库" aria-label="Permalink to “公开你的 Fossil 仓库”">​</a></h3><p>因为 Fossil 有个内置的 web 界面，所以 Fossil 不像 GitLab 和 Gitea 那样需要主机服务。Fossil 就是它自己的主机服务，只要你把它放在一台机器上就行了。在你公开你的 Fossil 仓库之前，你还需要通过 web 用户界面（UI）来配置一些信息：</p><p>使用 <code>ui</code> 子命令启动一个本地的实例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/klaatu/myprojectdir/</span></span>
<span class="line"><span>$ fossil ui</span></span></code></pre></div><p>“Users” 和 “Settings” 是安全相关的，“Configuration” 是项目属性相关的（包括一个合适的标题）。web 界面不仅仅是一个方便的功能。 它是能在生产环境中使用并作为 Fossil 项目的宿主机来使用的。它还有一些其他的高级选项，比如用户管理（或者叫自我管理）、在同一个服务器上与其他的 Fossil 仓库进行单点登录（SSO）。</p><p>当配置完成后，关掉 web 界面并按下 <code>Ctrl+C</code> 来停止 UI 引擎。像提交代码一样提交你的 web 修改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fossil commit -m &#39;web ui updates&#39;</span></span>
<span class="line"><span>New_Version: 11fe7f2855a3246c303df00ec725d0fca526fa0b83fa67c95db92283e8273c60</span></span></code></pre></div><p>现在你可以配置你的 Fossil 服务器了。</p><ol><li>把你的 Fossil 仓库（本例中是 <code>myproject.fossil</code>）复制到服务器，你只需要这一个文件。</li><li>如果你的服务器没有安装 Fossil，就在你的服务器上安装 Fossil。在服务器上安装的过程跟在本地一样。</li><li>在你的 <code>cgi-bin</code> 目录下（或它对应的目录，这取决于你的 HTTP 守护进程）创建一个名为 <code>repo_myproject.cgi</code> 的文件：</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/local/bin/fossil</span></span>
<span class="line"><span>repository: /home/klaatu/public_html/myproject.fossil</span></span></code></pre></div><p>添加可执行权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod +x repo_myproject.cgi</span></span></code></pre></div><p>你需要做的都已经做完了。现在可以通过互联网访问你的项目了。</p><p>你可以通过 CGI 脚本来访问 web UI，例如 <code>https://example.com/cgi-bin/repo_myproject.cgi</code>。</p><p>你也可以通过命令行来进行交互：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fossil clone https://klaatu@example.com/cgi-bin/repo_myproject.cgi</span></span></code></pre></div><p>在本地的克隆仓库中工作时，你需要使用 <code>push</code> 子命令把本地的修改推送到远程的仓库，使用 <code>pull</code> 子命令把远程的修改拉取到本地仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fossil push https://klaatu@example.com/cgi-bin/repo_myproject.cgi</span></span></code></pre></div><h3 id="使用-fossil-作为独立的托管" tabindex="-1">使用 Fossil 作为独立的托管 <a class="header-anchor" href="#使用-fossil-作为独立的托管" aria-label="Permalink to “使用 Fossil 作为独立的托管”">​</a></h3><p>Fossil 将大量的权力交到了你的手中（以及你的合作者的手中），让你不再依赖托管服务。本文只是简单的介绍了基本概念。你的代码项目还会用到很多有用的 Fossil 功能。尝试一下 Fossil。它不仅会改变你对版本控制的理解；它会让你不再考虑其他的版本控制系统。</p><hr>`,54)),i("p",null,[s[12]||(s[12]=a("via: ",-1)),n(e,{href:"https://opensource.com/article/20/11/fossil"},{default:l(()=>[...s[11]||(s[11]=[a("https://opensource.com/article/20/11/fossil",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=a("作者：",-1)),n(e,{href:"https://opensource.com/users/klaatu"},{default:l(()=>[...s[13]||(s[13]=[a("Klaatu",-1)])]),_:1}),s[18]||(s[18]=a(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[14]||(s[14]=[a("lujun9972",-1)])]),_:1}),s[19]||(s[19]=a(" 译者：",-1)),n(e,{href:"https://github.com/lxbwolf"},{default:l(()=>[...s[15]||(s[15]=[a("lxbwolf",-1)])]),_:1}),s[20]||(s[20]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[16]||(s[16]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[23]||(s[23]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[21]||(s[21]=[a("LCTT",-1)])]),_:1}),s[24]||(s[24]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:l(()=>[...s[22]||(s[22]=[a("Linux中国",-1)])]),_:1}),s[25]||(s[25]=a(" 荣誉推出",-1))])])}const v=t(c,[["render",h]]);export{C as __pageData,v as default};
